    static double bound(double v,double lo,double hi){return Double.isFinite(v)?Math.max(lo,Math.min(hi,v)):lo;}
    private static ArrayList<Integer> trackRows(ArrayList<Integer> tracks){Collections.sort(tracks);ArrayList<Integer> rows=new ArrayList<>();for(int track:tracks)if(rows.isEmpty()||rows.get(rows.size()-1)!=track)rows.add(track);return rows;}
    private static int rowOf(ArrayList<Integer> rows,int track){return Collections.binarySearch(rows,track);}
    void normalizeTracks(){
        ArrayList<Integer> rows=new ArrayList<>();for(int i=0;i<overlays.size();i++){Overlay o=overlays.get(i);if(o.track<0)o.track=i;rows.add(o.track);}rows=trackRows(rows);for(Overlay o:overlays)o.track=rowOf(rows,o.track);
        for(String type:new String[]{"Text","Image","Sticker"}){rows.clear();int ordinal=0;for(Caption c:captions)if(c.type.equals(type)){if(c.track<0)c.track=ordinal;rows.add(c.track);ordinal++;}rows=trackRows(rows);for(Caption c:captions)if(c.type.equals(type))c.track=rowOf(rows,c.track);}
        rows.clear();for(Audio a:audios)rows.add(Math.max(0,a.track));rows=trackRows(rows);for(Audio a:audios)a.track=rowOf(rows,Math.max(0,a.track));
        rows.clear();for(EffectClip e:effects)rows.add(Math.max(0,e.track));rows=trackRows(rows);for(EffectClip e:effects)e.track=rowOf(rows,Math.max(0,e.track));
    }
    int videoTracks(){normalizeTracks();int n=0;for(Overlay o:overlays)n=Math.max(n,o.track+1);return n;}
    int textTracks(){normalizeTracks();int n=0;for(Caption c:captions)if(c.type.equals("Text"))n=Math.max(n,c.track+1);return n;}
    int imageTracks(){normalizeTracks();int n=0;for(Caption c:captions)if(c.type.equals("Image"))n=Math.max(n,c.track+1);return n;}
    int stickerTracks(){normalizeTracks();int n=0;for(Caption c:captions)if(c.type.equals("Sticker"))n=Math.max(n,c.track+1);return n;}
    int effectTracks(){normalizeTracks();return effects.isEmpty()?0:1+effects.stream().mapToInt(e->e.track).max().orElse(-1);}
    int timelineHeight(){return 90+31*(videoTracks()+textTracks()+imageTracks()+stickerTracks()+audioTracks()+effectTracks());}
    Clip referenceClip(){return !clips.isEmpty()?clips.get(0):!overlays.isEmpty()?overlays.get(0).clip:!captions.isEmpty()?captions.get(0).style:null;}
    long videoDuration(){return clips.isEmpty()?0:offset(clips.size()-1)+clips.get(clips.size()-1).length();}
    long duration(){long result=videoDuration();for(Audio a:audios)result=Math.max(result,a.at+a.length());for(Overlay o:overlays)result=Math.max(result,o.at+o.clip.length());for(Caption c:captions)result=Math.max(result,c.end);for(EffectClip e:effects)result=Math.max(result,e.end);if(!music.isEmpty()&&musicEnd!=Long.MAX_VALUE)result=Math.max(result,musicEnd);return result;}
    long offset(int index){long end=0;for(int i=0;i<clips.size();i++){Clip c=clips.get(i);long at=c.timelineAt<0?end:Math.max(end,c.timelineAt);if(i==index)return at;end=at+c.length();}return end;}
